sections.sandboxCode:
// Интерактивный пример реактивности
const { ui, createState } = PotokSDK;

const state = createState({
  clicks: 0,
  lastClicked: "Никогда"
});

function draw() {
  ui.render(
    Card()
      .title("Счетчик кликов")
      .child(
        VStack()
          .spacing(12)
          .child(Text("Кликов зафиксировано: " + state.clicks).bold(true).size("lg"))
          .child(Text("Последнее нажатие: " + state.lastClicked).variant("secondary"))
          .child(
            Button("Клик!")
              .variant("primary")
              .onClick(() => {
                state.clicks++;
                state.lastClicked = new Date().toLocaleTimeString();
              })
          )
      )
  );
}

state.$subscribe(draw);
draw();

// Пример загрузки данных по сети
const { ui, http, createState } = PotokSDK;

const state = createState({
  loading: true,
  todoTitle: "",
  error: null
});

async function loadData() {
  try {
    const res = await http.get("https://jsonplaceholder.typicode.com/todos/1");
    state.todoTitle = res.data.title;
    state.loading = false;
  } catch (err) {
    state.error = err.message;
    state.loading = false;
  }
}

function render() {
  ui.render(
    Card()
      .title("Загрузка по сети")
      .child(
        VStack()
          .spacing(12)
          .child(
            state.loading 
              ? LoadingSpinner().message("Загружаем TODO с сервера...")
              : Text(state.error ? "Ошибка: " + state.error : "Задача с сервера: " + state.todoTitle)
          )
          .child(
            Button("Загрузить заново")
              .onClick(() => {
                state.loading = true;
                loadData();
              })
          )
      )
  );
}

state.$subscribe(render);
render();
loadData();

// Пример сохранения и загрузки настроек
const { ui, storage, createState } = PotokSDK;

const state = createState({
  savedValue: "Ничего не сохранено",
  inputValue: ""
});

async function initStorage() {
  const saved = await storage.local.getItem("user_custom_note");
  if (saved) {
    state.savedValue = saved;
  }
}

function render() {
  ui.render(
    Card()
      .title("Локальное хранилище")
      .child(
        VStack()
          .spacing(12)
          .child(Text("Сохранено в БД: " + state.savedValue).bold(true))
          .child(
            Input("note-input")
              .label("Новая запись")
              .value(state.inputValue)
              .onChange((val) => state.inputValue = val)
          )
          .child(
            Button("Сохранить в БД")
              .variant("primary")
              .onClick(async () => {
                await storage.local.setItem("user_custom_note", state.inputValue);
                state.savedValue = state.inputValue;
                ui.showHUD("success", "Значение успешно записано!");
              })
          )
      )
  );
}

state.$subscribe(render);
render();
initStorage();

